 * SPDX-License-Identifier: BSD-2-Clause
 *
 * Symbol versions of libnvrm.so.1.  Additive changes add to NVRM_1.0's
 * successor (NVRM_1.1, ...); a new major keeps the old library installed.
 *
 * PROVISIONAL: NVRM_1.0 is frozen at the first package release and not
 * before.  Until then the structures behind these calls may still change.
 */
NVRM_1.0 {
	global:
		nvrm_enumerate;
		nvrm_close;
		nvrm_backend_name;
		nvrm_rm_running_version;
		nvrm_device_count;
		nvrm_device_get;
		nvrm_device_info_get;
		nvrm_device_refresh;
		nvrm_strerror;
		nvrm_error_id;
		nvrm_reason_id;
		nvrm_reason_text;
		nvrm_source_name;
		nvrm_cap_name;
		nvrm_json_document;
		nvrm_json_header;
		nvrm_json_device;
		nvrm_json_end;
		nvrm_json_error;
		nvrm_json_schema;
		/* also in NVRM_1.2: the table grew; see nvrm_compat.c.  LLD needs the
		 * name in both nodes for the two .symver versions to be exported. */
		nvrm_info_nfields;
		nvrm_info_field;
	local:
		*;
};

/* API minor 1: memory and virtual address space (nvrm_mem(3)). */
NVRM_1.1 {
	global:
		nvrm_client_open;
		nvrm_client_close;
		nvrm_client_errmsg;
		nvrm_client_stats_get;
		nvrm_vaspace_info_get;
		nvrm_va_reserve;
		nvrm_va_release;
		nvrm_mem_alloc;
		nvrm_mem_register_user;
		nvrm_mem_free;
		nvrm_mem_info_get;
		nvrm_mem_map_gpu;
		nvrm_mem_unmap_gpu;
		nvrm_mem_map_cpu;
		nvrm_mem_unmap_cpu;
		nvrm_mem_read;
		nvrm_mem_write;
		nvrm_mem_export_fd;
		nvrm_mem_import_fd;
} NVRM_1.0;

/* API minor 2: version numbers (nvrm(3)) and the grown field table. */
NVRM_1.2 {
	global:
		nvrm_driver_version;
		nvrm_rm_api_version;
		nvrm_built_for_version;
		nvrm_library_version;
		nvrm_symbol_version;
		nvrm_schema_version;
		nvrm_reason_from_id;
		/* the default versions: they grew rows after 1.0; the 1.0 versions
		 * (nvrm_compat.c, .symver) return only the rows 1.0 had */
		nvrm_info_nfields;
		nvrm_info_field;
} NVRM_1.1;
